package sorting.core;

import java.util.function.Function;

public enum OptimizationProfile {
    SPEED("Speed optimized", config -> config
            .insertionThreshold(50)
            .trackMetrics(false)
            .validateInput(false)
            .threadPoolSize(Runtime.getRuntime().availableProcessors())),

    BALANCED("Balanced performance", config -> config
            .insertionThreshold(20)
            .trackMetrics(true)
            .validateInput(true)
            .threadPoolSize(Math.max(1, Runtime.getRuntime().availableProcessors() / 2))),

    SAFETY("Safety optimized", config -> config
            .insertionThreshold(10)
            .trackMetrics(true)
            .validateInput(true)
            .threadPoolSize(1)),

    MEMORY("Memory optimized", config -> config
            .insertionThreshold(5)
            .trackMetrics(false)
            .validateInput(false)
            .threadPoolSize(1));

    private final String description;
    private final Function<SortConfig.Builder, SortConfig.Builder> configurator;

    OptimizationProfile(String description, Function<SortConfig.Builder, SortConfig.Builder> configurator) {
        this.description = description;
        this.configurator = configurator;
    }

    public <T extends Comparable<T>> SortConfig<T> apply(SortConfig.Builder<T> builder) throws SortConfigurationException {
        @SuppressWarnings("unchecked")
        SortConfig.Builder<T> configured = (SortConfig.Builder<T>) configurator.apply(builder);
        return configured.build();
    }

    public String getDescription() {
        return description;
    }

    public static <T extends Comparable<T>> SortConfig<T> recommended() throws SortConfigurationException {
        return BALANCED.apply(SortConfig.builder());
    }
}

